package treecheck

import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"

	"github.com/Educentr/go-project-starter/internal/pkg/meta"
	"github.com/Educentr/go-project-starter/internal/pkg/templater"
)

// project is a throwaway tree that looks like a generated project: files on
// disk plus the meta.yaml a run would have left behind.
type project struct {
	dir  string
	recs meta.Manifest
}

// A generated file as the templater leaves it: the generated region ends with
// the disclaimer line, everything after it belongs to whoever edits the file.
const (
	genBody  = "package app\n\n// Code generated by go-project-starter.\n// If you need you can add your code after this message\n"
	userCode = "\nfunc mine() string { return \"kept\" }\n"
	specBody = "openapi: 3.0.0\ninfo:\n  title: example\n"
)

func newProject(t *testing.T) *project {
	t.Helper()

	dir := t.TempDir()

	if err := os.MkdirAll(filepath.Join(dir, meta.DirName), 0755); err != nil {
		t.Fatalf("create %s: %v", meta.DirName, err)
	}

	return &project{dir: dir}
}

// write puts a file on disk without recording it in the manifest.
func (p *project) write(t *testing.T, rel, content string) string {
	t.Helper()

	path := filepath.Join(p.dir, filepath.FromSlash(rel))

	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		t.Fatalf("create dir for %s: %v", rel, err)
	}

	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		t.Fatalf("write %s: %v", rel, err)
	}

	return path
}

// track records a file in the manifest, hashing it the way the generator does:
// the generated region for a generated file, the whole file for a copied one.
func (p *project) track(t *testing.T, rel, kind, content string) {
	t.Helper()

	hash := meta.HashContent([]byte(content))

	if kind == meta.KindGenerated {
		var err error
		if hash, err = templater.GeneratedRegionHash(rel, []byte(content)); err != nil {
			t.Fatalf("hash %s: %v", rel, err)
		}
	}

	p.recs = append(p.recs, meta.FileRecord{Path: rel, Kind: kind, Hash: hash})
}

// generated writes a generated file and records it, as one run would.
func (p *project) generated(t *testing.T, rel, content string) string {
	t.Helper()

	p.track(t, rel, meta.KindGenerated, content)

	return p.write(t, rel, content)
}

// copied writes a file copied into the project as-is and records it.
func (p *project) copied(t *testing.T, rel, content string) string {
	t.Helper()

	p.track(t, rel, meta.KindCopied, content)

	return p.write(t, rel, content)
}

// saveMeta writes meta.yaml at the given schema version. The version is passed
// in rather than taken from Meta.Save, which always stamps the current one —
// the check has to be exercised against older and newer trees too.
func (p *project) saveMeta(t *testing.T, version int) {
	t.Helper()

	data, err := yaml.Marshal(meta.Meta{Version: version, Manifest: p.recs.Normalize()})
	if err != nil {
		t.Fatalf("marshal meta: %v", err)
	}

	if err := os.WriteFile(filepath.Join(p.dir, meta.DirName, meta.FileName), data, 0644); err != nil {
		t.Fatalf("write meta.yaml: %v", err)
	}
}

// run saves the manifest at the current schema version and checks the tree.
func (p *project) run(t *testing.T) (Result, error) {
	t.Helper()

	p.saveMeta(t, meta.CurrentVersion)

	return Run(p.dir)
}

// cleanProject is the common fixture: one generated file carrying user code and
// one copied spec, both matching their records.
func cleanProject(t *testing.T) *project {
	t.Helper()

	p := newProject(t)
	p.generated(t, "internal/app/psg_app_gen.go", genBody+userCode)
	p.copied(t, "api/rest/example/v1/example.swagger.yml", specBody)

	return p
}

// findingFor returns the single finding for rel, failing when the check
// reported a different number of them.
func findingFor(t *testing.T, res Result, rel string) Finding {
	t.Helper()

	if len(res.Findings) != 1 {
		t.Fatalf("want exactly one finding, got %d: %s", len(res.Findings), res.Report())
	}

	if res.Findings[0].Path != rel {
		t.Fatalf("finding path = %q, want %q", res.Findings[0].Path, rel)
	}

	return res.Findings[0]
}

func TestRunUntouchedTree(t *testing.T) {
	p := cleanProject(t)

	res, err := p.run(t)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	if !res.OK() {
		t.Fatalf("untouched tree must pass, got:\n%s", res.Report())
	}

	if res.Checked != 2 {
		t.Errorf("Checked = %d, want 2", res.Checked)
	}

	if !strings.Contains(res.Report(), meta.DirName+"/"+meta.FileName) {
		t.Errorf("report must name the manifest it read:\n%s", res.Report())
	}
}

// The point of the whole feature: code below the marker is the user's and is
// not part of what the check compares.
func TestRunUserCodeBelowMarker(t *testing.T) {
	p := newProject(t)
	rel := "internal/app/psg_app_gen.go"

	p.generated(t, rel, genBody)
	p.write(t, rel, genBody+userCode+"\n// more of mine\n")

	res, err := p.run(t)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	if !res.OK() {
		t.Fatalf("edits below the marker must pass, got:\n%s", res.Report())
	}
}

func TestRunEditAboveMarker(t *testing.T) {
	p := cleanProject(t)
	rel := "internal/app/psg_app_gen.go"

	p.write(t, rel, "// hand edit\n"+genBody+userCode)

	res, err := p.run(t)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	f := findingFor(t, res, rel)

	if f.Reason != ReasonModified {
		t.Errorf("Reason = %q, want %q", f.Reason, ReasonModified)
	}

	if f.Kind != meta.KindGenerated {
		t.Errorf("Kind = %q, want %q", f.Kind, meta.KindGenerated)
	}

	if f.Expected == "" || f.Actual == "" || f.Expected == f.Actual {
		t.Errorf("both hashes must be reported and differ: expected=%q actual=%q", f.Expected, f.Actual)
	}

	// The gate is read in a CI log: the path and both hashes have to be in it.
	report := res.Report()
	for _, want := range []string{rel, "(" + meta.KindGenerated + ")", f.Expected, f.Actual, hintGenerated} {
		if !strings.Contains(report, want) {
			t.Errorf("report must contain %q:\n%s", want, report)
		}
	}
}

func TestRunEditedCopiedSpec(t *testing.T) {
	p := cleanProject(t)
	rel := "api/rest/example/v1/example.swagger.yml"

	p.write(t, rel, specBody+"  version: edited-in-place\n")

	res, err := p.run(t)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	f := findingFor(t, res, rel)

	if f.Reason != ReasonModified || f.Kind != meta.KindCopied {
		t.Errorf("got reason %q kind %q, want %q/%q", f.Reason, f.Kind, ReasonModified, meta.KindCopied)
	}

	// A copied spec is not an edit point anywhere in the file, and the advice
	// for it is the one generation already gives.
	if !strings.Contains(res.Report(), meta.CopiedFileDriftHint) {
		t.Errorf("report must reuse the copied-drift hint:\n%s", res.Report())
	}
}

// A deleted generated file is a change of the generated area too: the tree no
// longer holds what the generator produced.
func TestRunMissingFile(t *testing.T) {
	p := cleanProject(t)
	rel := "internal/app/psg_app_gen.go"

	if err := os.Remove(filepath.Join(p.dir, filepath.FromSlash(rel))); err != nil {
		t.Fatalf("remove %s: %v", rel, err)
	}

	res, err := p.run(t)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	f := findingFor(t, res, rel)

	if f.Reason != ReasonMissing {
		t.Errorf("Reason = %q, want %q", f.Reason, ReasonMissing)
	}

	if f.Actual != "" {
		t.Errorf("a missing file has no hash on disk, got %q", f.Actual)
	}

	if strings.Contains(res.Report(), "on disk:") {
		t.Errorf("report must not print an on-disk hash for a missing file:\n%s", res.Report())
	}
}

// Removing the marker used to abort the run with "error split disclaimer in
// file …" — the check reports it as what it is instead.
func TestRunMarkerRemoved(t *testing.T) {
	p := cleanProject(t)
	rel := "internal/app/psg_app_gen.go"

	p.write(t, rel, strings.ReplaceAll(genBody, "If you need you can add your code after this message", "")+userCode)

	res, err := p.run(t)
	if err != nil {
		t.Fatalf("a lost marker is a finding, not a failure: %v", err)
	}

	f := findingFor(t, res, rel)

	if f.Reason != ReasonMarkerLost {
		t.Errorf("Reason = %q, want %q", f.Reason, ReasonMarkerLost)
	}

	if !strings.Contains(res.Report(), "disclaimer marker was removed") {
		t.Errorf("report must explain the lost marker:\n%s", res.Report())
	}
}

func TestRunNonRegularEntry(t *testing.T) {
	p := cleanProject(t)
	rel := "internal/app/psg_app_gen.go"
	path := filepath.Join(p.dir, filepath.FromSlash(rel))

	// A symlink to a file with the very content the manifest expects: the hash
	// would match, the entry on the path still is not the generated file.
	decoy := p.write(t, "decoy.txt", genBody+userCode)

	if err := os.Remove(path); err != nil {
		t.Fatalf("remove %s: %v", rel, err)
	}

	if err := os.Symlink(decoy, path); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}

	res, err := p.run(t)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	if f := findingFor(t, res, rel); f.Reason != ReasonNotRegular {
		t.Errorf("Reason = %q, want %q", f.Reason, ReasonNotRegular)
	}
}

// Files without a disclaimer marker (JSON, .keep, go.sum) are generated whole,
// and that is how their hash is recorded — the check must follow the same rule.
func TestRunFileWithoutMarker(t *testing.T) {
	p := newProject(t)
	rel := "configs/dashboard.json"

	p.generated(t, rel, `{"title":"service"}`)

	res, err := p.run(t)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	if !res.OK() {
		t.Fatalf("untouched marker-less file must pass, got:\n%s", res.Report())
	}

	p.write(t, rel, `{"title":"edited"}`)

	res, err = p.run(t)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	if f := findingFor(t, res, rel); f.Reason != ReasonModified {
		t.Errorf("Reason = %q, want %q", f.Reason, ReasonModified)
	}
}

func TestRunSkippedRecords(t *testing.T) {
	p := cleanProject(t)

	// No recorded hash: the file was written, its content was not hashed.
	p.recs = append(p.recs, meta.FileRecord{Path: "internal/app/psg_nohash_gen.go", Kind: meta.KindGenerated})
	p.write(t, "internal/app/psg_nohash_gen.go", genBody+"// whatever\n")

	// User-owned: the generator hands the file over after writing it once, so
	// it is outside the area this check is about. Such a record can only come
	// from a hand-edited manifest, hence the explicit guard.
	p.recs = append(p.recs, meta.FileRecord{Path: "go.mod", Kind: meta.KindGenerated, Hash: "deadbeef"})
	p.write(t, "go.mod", "module example.com/app\n\ngo 1.27\n")

	res, err := p.run(t)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	if !res.OK() {
		t.Fatalf("records with nothing to compare must not produce findings, got:\n%s", res.Report())
	}

	if res.Skipped != 2 {
		t.Errorf("Skipped = %d, want 2", res.Skipped)
	}

	if res.Checked != 2 {
		t.Errorf("Checked = %d, want 2", res.Checked)
	}

	// A green verdict has to say it stands for fewer records than the manifest
	// holds, or it reads as "everything was verified".
	if !strings.Contains(res.Report(), "nothing to compare") {
		t.Errorf("report must disclose the records it did not compare:\n%s", res.Report())
	}
}

// The verdict must not depend on anything but the manifest and the tree: no
// project.yaml is read, so no spec source is resolved and no contract
// repository has to be reachable.
func TestRunWithoutConfig(t *testing.T) {
	p := cleanProject(t)
	p.saveMeta(t, meta.CurrentVersion)

	cfg := filepath.Join(p.dir, meta.DirName, "project.yaml")
	if _, err := os.Stat(cfg); !errors.Is(err, fs.ErrNotExist) {
		t.Fatalf("fixture must carry no project.yaml, stat err = %v", err)
	}

	res, err := Run(p.dir)
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	if !res.OK() {
		t.Fatalf("check must pass without a config, got:\n%s", res.Report())
	}
}

// "Writes nothing" is a property of the gate, not a side note: it runs on
// trees that are about to be committed, and on CI checkouts shared with other
// steps. meta.yaml included — refreshing hashes is generation's job.
func TestRunWritesNothing(t *testing.T) {
	p := cleanProject(t)
	p.saveMeta(t, meta.CurrentVersion)

	// A drifted file, so the check takes the reporting path too.
	p.write(t, "api/rest/example/v1/example.swagger.yml", specBody+"  version: edited\n")

	before := snapshot(t, p.dir)

	if _, err := Run(p.dir); err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	after := snapshot(t, p.dir)

	if len(before) != len(after) {
		t.Fatalf("file count changed: %d -> %d", len(before), len(after))
	}

	for path, state := range before {
		if after[path] != state {
			t.Errorf("%s changed: %q -> %q", path, state, after[path])
		}
	}
}

// snapshot maps every file in the tree to its content and modification time.
func snapshot(t *testing.T, dir string) map[string]string {
	t.Helper()

	state := make(map[string]string)

	err := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}

		info, err := d.Info()
		if err != nil {
			return err
		}

		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}

		state[path] = info.ModTime().String() + ":" + meta.HashContent(content)

		return nil
	})
	if err != nil {
		t.Fatalf("walk %s: %v", dir, err)
	}

	return state
}

// A tree the check cannot judge must say so and fail, never report success:
// a green gate is a claim about the tree, and none of these cases supports one.
func TestRunUncheckableTree(t *testing.T) {
	tests := []struct {
		name    string
		prepare func(t *testing.T) string
		want    error
		wantMsg string
	}{
		{
			name: "no meta.yaml at all",
			prepare: func(t *testing.T) string {
				t.Helper()

				p := cleanProject(t)

				return p.dir
			},
			want:    ErrMetaNotFound,
			wantMsg: "committed with the project",
		},
		{
			name: "project older than the manifest",
			prepare: func(t *testing.T) string {
				t.Helper()

				p := cleanProject(t)
				p.recs = nil
				p.saveMeta(t, 1)

				return p.dir
			},
			want:    ErrNoManifest,
			wantMsg: "regenerate",
		},
		{
			name: "manifest from a newer generator",
			prepare: func(t *testing.T) string {
				t.Helper()

				p := cleanProject(t)
				p.saveMeta(t, meta.CurrentVersion+1)

				return p.dir
			},
			want:    ErrFutureMeta,
			wantMsg: "GPSVERSION",
		},
		{
			name: "record kind this binary cannot hash",
			prepare: func(t *testing.T) string {
				t.Helper()

				p := cleanProject(t)
				p.recs = meta.Manifest{{Path: "internal/app/psg_app_gen.go", Kind: "rendered", Hash: "deadbeef"}}
				p.saveMeta(t, meta.CurrentVersion)

				return p.dir
			},
			want: ErrUnknownKind,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			res, err := Run(tt.prepare(t))
			if !errors.Is(err, tt.want) {
				t.Fatalf("Run() error = %v, want %v", err, tt.want)
			}

			if tt.wantMsg != "" && !strings.Contains(err.Error(), tt.wantMsg) {
				t.Errorf("error must tell the operator what to do, missing %q: %v", tt.wantMsg, err)
			}

			if res.OK() && len(res.Findings) == 0 && res.Checked != 0 {
				t.Errorf("a failed check must not return a passing result: %+v", res)
			}
		})
	}
}

// Each reason gets its own advice, and only the ones actually present.
func TestReportHints(t *testing.T) {
	tests := []struct {
		name     string
		findings []Finding
		want     []string
		notWant  []string
	}{
		{
			name:     "generated only",
			findings: []Finding{{Kind: meta.KindGenerated, Reason: ReasonModified}},
			want:     []string{hintGenerated},
			notWant:  []string{meta.CopiedFileDriftHint, hintMissing, hintNotRegular},
		},
		{
			name:     "copied only",
			findings: []Finding{{Kind: meta.KindCopied, Reason: ReasonModified}},
			want:     []string{meta.CopiedFileDriftHint},
			notWant:  []string{hintGenerated},
		},
		{
			name:     "missing file of either kind",
			findings: []Finding{{Kind: meta.KindCopied, Reason: ReasonMissing}},
			want:     []string{hintMissing},
			notWant:  []string{meta.CopiedFileDriftHint, hintGenerated},
		},
		{
			name: "same reason twice is advised once",
			findings: []Finding{
				{Path: "a", Kind: meta.KindGenerated, Reason: ReasonModified},
				{Path: "b", Kind: meta.KindGenerated, Reason: ReasonModified},
			},
			want: []string{hintGenerated},
		},
		{
			name:     "non-regular entry",
			findings: []Finding{{Kind: meta.KindGenerated, Reason: ReasonNotRegular}},
			want:     []string{hintNotRegular},
			notWant:  []string{hintGenerated},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			report := Result{MetaPath: "m", Checked: len(tt.findings), Findings: tt.findings}.Report()

			for _, want := range tt.want {
				if strings.Count(report, want) != 1 {
					t.Errorf("report must carry %q exactly once:\n%s", want, report)
				}
			}

			for _, notWant := range tt.notWant {
				if strings.Contains(report, notWant) {
					t.Errorf("report must not carry %q:\n%s", notWant, report)
				}
			}
		})
	}
}
